/**
 * The interview engine every `init` flow shares: template `init.json`
 * questions and the create-agent rounds.
 * Answers arrive from flags or an answers file, from a TTY prompt, or from
 * defaults, in that order. Nothing prompts without a TTY.
 */
import { createInterface } from "node:readline";
import * as z from "zod/v4";
import { describeError } from "../describe-error.js";
/** A field whose answers are checked against its schema before they are kept. */
export function field(round, question, schema, options) {
    const check = question.check;
    return {
        round,
        schema,
        options,
        question: {
            ...question,
            check: (value, answers) => {
                const parsed = schema.safeParse(question.multi ? listAnswer(value) : value);
                return parsed.success ? check?.(value, answers) : parsed.error.issues[0]?.message;
            },
        },
    };
}
export function checkedString(error) {
    return z.string().superRefine((value, ctx) => {
        const message = error(value);
        if (message !== undefined) {
            ctx.addIssue({ code: "custom", message });
        }
    });
}
export async function collectAnswers(input) {
    if (input.ask !== undefined) {
        return collect(input, input.ask);
    }
    const terminal = terminalSession(process.stdin, process.stdout, input.show);
    try {
        return await collect(input, terminal.ask);
    }
    finally {
        terminal.close();
    }
}
async function collect(input, ask) {
    const given = input.given ?? {};
    const out = input.out ?? ((text) => process.stdout.write(text));
    const missing = input.missing ?? ((q) => `pass --var ${q.id}=... (${q.prompt})`);
    const answers = {};
    const defaulted = [];
    for (const question of input.questions) {
        if (question.when !== undefined && !question.when(answers)) {
            continue;
        }
        const fallback = typeof question.default === "function" ? question.default(answers) : question.default;
        if (question.id in given || !input.interactive) {
            const supplied = given[question.id]?.trim();
            const raw = supplied || fallback;
            if (raw === undefined || raw === "") {
                if (question.optional) {
                    continue;
                }
                // Skipping would scaffold the template's sample answer (e.g. owner/repo).
                return { ok: false, error: `${question.id} is required: ${missing(question)}` };
            }
            const parsed = parseAnswer(question, raw, answers);
            if (!parsed.ok) {
                return parsed;
            }
            if (!supplied) {
                defaulted.push(question.id);
            }
            answers[question.id] = parsed.value;
            continue;
        }
        for (;;) {
            let line;
            try {
                line = await ask(question, fallback);
            }
            catch (error) {
                return { ok: false, error: `${question.id}: ${describeError(error)}` };
            }
            const value = line.trim() === "" && fallback !== undefined ? fallback : line;
            if (value.trim() === "" && question.optional) {
                break;
            }
            const parsed = parseAnswer(question, value, answers);
            if (parsed.ok) {
                answers[question.id] = parsed.value;
                break;
            }
            out(`${parsed.error}\n`);
        }
    }
    return { ok: true, answers, defaulted };
}
function choiceValues(question) {
    return (question.choices ?? []).map((choice) => typeof choice === "string" ? choice : choice.value);
}
/** A raw list answer as items: `none` and blank are empty. */
export function listAnswer(raw) {
    if (raw === undefined || raw.trim() === "none") {
        return [];
    }
    return raw
        .split(",")
        .map((item) => item.trim())
        .filter((item) => item !== "");
}
const INPUT_ENDED = "Input ended before every question was answered.";
/**
 * One readline session per interview, opened at the first prompt. Its line
 * iterator keeps lines that arrive before their prompt (a paste), and end
 * of input fails the waiting question instead of leaving it pending.
 */
export function terminalSession(input, output, show = (text) => text) {
    let session;
    const open = () => {
        const rl = createInterface({ input, output });
        const opened = { rl, lines: rl[Symbol.asyncIterator](), closed: false };
        rl.on("close", () => {
            opened.closed = true;
        });
        return opened;
    };
    return {
        ask: async (question, fallback) => {
            session ??= open();
            // After close, rl.prompt() resumes input and prints a stray prompt.
            if (!session.closed) {
                if (question.hint !== undefined) {
                    output.write(show(`  ${question.hint}\n`));
                }
                session.rl.setPrompt(show(`${question.prompt}${promptSuffix(question, fallback)} `));
                session.rl.prompt();
            }
            const next = await session.lines.next();
            if (next.done === true) {
                output.write("\n");
                throw new Error(INPUT_ENDED);
            }
            return next.value;
        },
        close: () => session?.rl.close(),
    };
}
function promptSuffix(question, fallback) {
    const values = choiceValues(question);
    if (values.length > 0) {
        const list = question.multi ? values.join(", ") : values.join("/");
        return ` [${list}]${fallback === undefined ? "" : ` (default: ${fallback})`}`;
    }
    if (fallback !== undefined) {
        return ` [${fallback}]`;
    }
    if (question.placeholder !== undefined) {
        return ` (${question.placeholder})`;
    }
    return "";
}
function parseAnswer(question, raw, answers) {
    const trimmed = raw.trim();
    if (trimmed === "") {
        return { ok: false, error: `${question.id} is required.` };
    }
    const values = choiceValues(question);
    let value = trimmed;
    if (question.multi) {
        const items = trimmed === "all" && values.length > 0 ? values : listAnswer(trimmed);
        const unknown = question.other ? [] : items.filter((item) => !values.includes(item));
        if (values.length > 0 && unknown.length > 0) {
            return {
                ok: false,
                error: `${question.id} accepts ${values.join(", ")}, all, or none (got ${unknown.join(", ")}).`,
            };
        }
        value = items.length === 0 ? "none" : [...new Set(items)].join(", ");
    }
    else if (values.length > 0 && !question.other) {
        if (!values.includes(trimmed)) {
            return { ok: false, error: `${question.id} must be one of ${values.join(", ")}.` };
        }
    }
    else if (question.parse !== undefined) {
        try {
            value = question.parse(trimmed);
        }
        catch (error) {
            return { ok: false, error: describeError(error) };
        }
    }
    const error = question.check?.(value, answers);
    return error === undefined
        ? { ok: true, value }
        : { ok: false, error: `${question.id}: ${error}` };
}
